const m = $json;
const num = (v) => Number(v) || 0;
const total = num(m.analysed_total);
const rate = (n) => (total ? num(n) / total : 0);
const days = num(m.baseline_days);
const medTotal = num(m.baseline_median_total);
const medLong = num(m.baseline_too_long_rate);
const medAiFail = num(m.baseline_ai_fail_rate);

const breaches = [];

// 固定判据：30 天基线里 tag/sentiment 违规恒为 0，ascii 引号单日最多 2
if (num(m.tag_invalid) > 0) breaches.push('tag_invalid=' + num(m.tag_invalid) + ' (baseline 0)');
if (num(m.sentiment_invalid) > 0) breaches.push('sentiment_invalid=' + num(m.sentiment_invalid) + ' (baseline 0)');
if (num(m.summary_ascii_quote) > 2) breaches.push('ascii_quote=' + num(m.summary_ascii_quote) + ' (baseline max 2/day)');

// 滚动判据：基线不足 7 天时不判，避免冷启动误报
if (days >= 7) {
  const longLimit = Math.max(medLong * 2, 0.05);
  const longRate = rate(m.summary_too_long);
  if (longRate > longLimit) {
    breaches.push('too_long rate ' + (longRate * 100).toFixed(1) + '% > limit '
      + (longLimit * 100).toFixed(1) + '% (14d median ' + (medLong * 100).toFixed(1) + '%)');
  }
  if (medTotal > 0 && total < medTotal * 0.5) {
    breaches.push('volume ' + total + ' < half of 14d median ' + medTotal);
  }
  const attempted = total + num(m.ai_failed);
  const failRate = attempted ? num(m.ai_failed) / attempted : 0;
  const failLimit = Math.max(medAiFail * 2, 0.12);
  if (failRate > failLimit) {
    breaches.push('ai_failed rate ' + (failRate * 100).toFixed(1) + '% > limit '
      + (failLimit * 100).toFixed(1) + '% (14d median ' + (medAiFail * 100).toFixed(1) + '%)');
  }
}

const summary_line = 'analysed=' + total
  + ' tag_invalid=' + num(m.tag_invalid)
  + ' too_long=' + num(m.summary_too_long)
  + ' no_end_punct=' + num(m.summary_no_end_punct)
  + ' ascii_quote=' + num(m.summary_ascii_quote)
  + ' sentiment_invalid=' + num(m.sentiment_invalid)
  + ' ai_failed=' + num(m.ai_failed)
  + ' fetch_failed=' + num(m.fetch_failed)
  + ' | baseline ' + days + 'd median_total=' + medTotal
  + ' median_too_long=' + (medLong * 100).toFixed(1) + '%'
  + ' median_ai_fail=' + (medAiFail * 100).toFixed(1) + '%';

return [{ json: Object.assign({}, m, { breaches: breaches, summary_line: summary_line }) }];
